// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.llm.layerimport com.roshan.persona.brain.bus.BrainBusimport com.roshan.persona.brain.bus.BrainEventimport com.roshan.persona.brain.context.BrainContextimport com.roshan.persona.brain.llm.context.ContextInjectorimport com.roshan.persona.brain.llm.cost.LlmCostTrackerimport com.roshan.persona.brain.llm.provider.CloudLlmProviderimport com.roshan.persona.brain.llm.provider.CloudProviderConfigimport com.roshan.persona.brain.llm.provider.GenerationConfigimport com.roshan.persona.brain.llm.provider.GenerationResultimport com.roshan.persona.brain.llm.registry.CloudProviderRegistryimport com.roshan.persona.brain.skill.CredentialVaultInterfaceimport com.roshan.persona.brain.skill.SkillOutputimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport kotlinx.coroutines.withTimeoutOrNullimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Layer 4: Cloud LLM. * * Orchestrates cloud LLM inference via the following pipeline: * *   1. **Opt-in check** — only runs if user has cloud enabled (privacy fix #6). *      If [com.roshan.persona.brain.context.PrivacySettings.cloudLlmEnabled] is *      false, returns Failure immediately — no cloud call ever made. * *   2. **Provider selection** — pick the best enabled provider based on: *        - Explicit user preference (if request specifies a provider) *        - Lowest cost (cheapest provider that supports the model) *        - Highest availability (skip providers with recent failures) * *   3. **Budget check** — call [LlmCostTracker.checkBudget] before the call. *      If monthly cap would be exceeded, return Failure with budget error. * *   4. **Context injection + PII scrubbing** — [ContextInjector.buildPrompt] *      assembles the prompt, then [ContextInjector.scrubForCloud] strips PII. *      Critical: cloud NEVER sees unscrubbed PII. * *   5. **Generation** — call [CloudLlmProvider.generate] with streaming *      token callback. Enforced via [BrainBudget.maxLatencyMs] timeout. * *   6. **Cost tracking** — record actual token usage + USD cost in *      [LlmCostTracker]. Updates monthly spend. * *   7. **Confidence check** — same as LocalLlmLayer: short/repetitive/LENGTH *      responses flagged as Partial with warning. * * ## Privacy Contract (Strong — per ADR 0011) * *   - Default behavior: cloud is OFF. User must explicitly opt-in per provider. *   - PII is scrubbed BEFORE any cloud call (phone/email/Aadhaar/card). *   - All cloud calls are HTTPS (enforced by [CloudProviderConfig.baseUrl]). *   - Cert pinning applied if [CloudProviderConfig.certPins] is non-empty. *   - API keys never logged, never serialized, only used at call time. *   - Monthly budget cap enforced — runaway costs impossible. * * ## When CloudLlmLayer Is Called * * The [com.roshan.persona.brain.llm.router.HybridLlmRouter] decides when to * call this layer: *   - User explicitly asked for cloud ("ask cloud: ...") *   - LocalLlmLayer returned Failure AND user has cloud enabled *   - Long context (>4k tokens) AND user has cloud enabled *   - User tapped "Verify with cloud" on a low-confidence LocalLlmLayer response * * @see <a href="docs/spec/module2-spec-review.pdf">§8 Layer 4</a> */@Singletonclass CloudLlmLayer(    private val registry: CloudProviderRegistry,    private val costTracker: LlmCostTracker,    private val contextInjector: ContextInjector,    private val credentialVault: CredentialVaultInterface,    private val brainBus: BrainBus,    private val providerFactory: (CloudProviderConfig) -> CloudLlmProvider,    private val lowConfidenceMinTokens: Int = DEFAULT_LOW_CONFIDENCE_MIN_TOKENS,    private val lowConfidenceRepetitionThreshold: Float = DEFAULT_REPETITION_THRESHOLD,) {    /**     * Process [userInput] through the cloud LLM layer.     *     * @param userInput the user's text input (already context-resolved by L0)     * @param context the brain context     * @param preferredProviderId optional — force use of this provider     *   (e.g., "openai", "anthropic"). If null, layer picks best provider.     * @param preferredModel optional — force use of this model     * @param generationConfig LLM sampling params     * @param onToken streaming callback for each generated token     * @return [SkillOutput] wrapped in [Result]     */    suspend fun process(        userInput: String,        context: BrainContext,        preferredProviderId: String? = null,        preferredModel: String? = null,        generationConfig: GenerationConfig = GenerationConfig.BALANCED,        onToken: (String) -> Unit = {},    ): Result<SkillOutput> {        val startNanos = System.nanoTime()        val correlationId = context.correlationId        // ─── Step 1: Opt-in check (privacy fix #6) ────────────────────────        if (!context.userContext.privacySettings.cloudLlmEnabled) {            Timber.tag("NOUS.L4").w("Cloud LLM disabled by user (privacy mode) — refusing call")            return Result.Success(                data = SkillOutput.Failure(                    error = AppError.Configuration.InvalidProviderConfig(                        reason = "Cloud LLM is disabled in privacy settings",                    ),                    userMessage = "Cloud AI is disabled. Enable it in Settings → Privacy to use cloud providers.",                ),                correlationId = correlationId,                durationNanos = System.nanoTime() - startNanos,                metadata = mapOf("privacy_blocked" to "true"),            )        }        // ─── Step 2: Provider selection ───────────────────────────────────        val providerConfig = selectProvider(preferredProviderId)            ?: return Result.Success(                data = SkillOutput.Failure(                    error = AppError.Configuration.InvalidProviderConfig(                        reason = "No cloud provider is enabled. Enable one in Settings → AI Models.",                    ),                    userMessage = "No cloud provider is enabled. Add or enable one in Settings → AI Models → Cloud Providers.",                ),                correlationId = correlationId,                durationNanos = System.nanoTime() - startNanos,            )        // ─── Step 3: Budget check ─────────────────────────────────────────        val model = preferredModel ?: providerConfig.defaultModel        val estimatedInputTokens = contextInjector.estimateTokens(userInput) +            contextInjector.estimateTokens(providerConfig.displayName) +            ESTIMATED_SYSTEM_PROMPT_TOKENS        val estimatedOutputTokens = generationConfig.maxTokens        val estimatedCostUsd = providerConfig.computeCostUsd(            inputTokens = estimatedInputTokens,            outputTokens = estimatedOutputTokens,        )        val budgetResult = costTracker.checkBudget(            monthlyBudgetUsd = context.userContext.monthlyLlmBudgetUsd,            estimatedCostUsd = estimatedCostUsd,        )        if (budgetResult is Result.Failure) {            Timber.tag("NOUS.L4").w("Budget exceeded — refusing cloud call")            return Result.Success(                data = SkillOutput.Failure(                    error = budgetResult.error,                    userMessage = "Monthly LLM budget exceeded (\$${"%.2f".format(context.userContext.monthlyLlmBudgetUsd)}). " +                        "Increase it in Settings → Privacy → Monthly Budget.",                ),                correlationId = correlationId,                durationNanos = System.nanoTime() - startNanos,                metadata = mapOf(                    "provider" to providerConfig.id,                    "estimated_cost" to estimatedCostUsd.toString(),                ),            )        }        // ─── Step 4: Build prompt + PII scrub (privacy fix #6) ────────────        val promptBuild = contextInjector.buildPrompt(            userInput = userInput,            context = context,            maxTokens = (providerConfig.maxContextLength - generationConfig.maxTokens).coerceAtLeast(0),        )        val scrubbedPrompt = contextInjector.scrubForCloud(promptBuild.prompt)        if (scrubbedPrompt != promptBuild.prompt) {            Timber.tag("NOUS.L4").i("PII scrubbed from prompt before cloud call")        }        // ─── Step 5: Generate (with budget timeout) ───────────────────────        val provider = try {            providerFactory(providerConfig)        } catch (t: Throwable) {            return Result.Failure(                error = AppError.Unknown(cause = t, correlationId = correlationId),                correlationId = correlationId,                durationNanos = System.nanoTime() - startNanos,            )        }        brainBus.emit(BrainEvent.LlmCallStarted(            provider = providerConfig.id,            modelId = model,            correlationId = correlationId,        ))        val generationTimeoutMs = minOf(context.budget.maxLatencyMs, providerConfig.timeoutMs)        val generationResult = withTimeoutOrNull(generationTimeoutMs) {            provider.generate(                prompt = scrubbedPrompt,                model = model,                config = generationConfig,                onToken = onToken,            )        }        if (generationResult == null) {            // Timeout            val timeoutError = AppError.Network.Timeout(                durationMs = generationTimeoutMs,                cause = null,            )            costTracker.recordUsage(                providerId = providerConfig.id,                inputTokens = estimatedInputTokens,                outputTokens = 0,                costUsd = 0f,                success = false,            )            brainBus.emit(BrainEvent.LlmCallFailed(                provider = providerConfig.id,                modelId = model,                error = timeoutError,                correlationId = correlationId,            ))            return Result.Failure(                error = timeoutError,                correlationId = correlationId,                durationNanos = System.nanoTime() - startNanos,            )        }        when (generationResult) {            is Result.Failure -> {                costTracker.recordUsage(                    providerId = providerConfig.id,                    inputTokens = estimatedInputTokens,                    outputTokens = 0,                    costUsd = 0f,                    success = false,                )                brainBus.emit(BrainEvent.LlmCallFailed(                    provider = providerConfig.id,                    modelId = model,                    error = generationResult.error,                    correlationId = correlationId,                ))                return Result.Failure(                    error = generationResult.error,                    correlationId = correlationId,                    durationNanos = System.nanoTime() - startNanos,                )            }            is Result.Success -> { /* fall through */ }            is Result.Partial -> { /* shouldn't happen, but handle */ }        }        // Safe cast: we already handled Failure above (returned early).        // At this point, generationResult must be Success or Partial.        val generation = when (generationResult) {            is Result.Success -> generationResult.data            is Result.Partial -> generationResult.data            is Result.Failure -> return Result.Failure(                error = generationResult.error,                correlationId = correlationId,                durationNanos = System.nanoTime() - startNanos,            )        }        // ─── Step 6: Cost tracking ────────────────────────────────────────        val actualCostUsd = providerConfig.computeCostUsd(            inputTokens = generation.promptTokens,            outputTokens = generation.tokensGenerated,        )        costTracker.recordUsage(            providerId = providerConfig.id,            inputTokens = generation.promptTokens,            outputTokens = generation.tokensGenerated,            costUsd = actualCostUsd,            success = true,        )        brainBus.emit(BrainEvent.LlmCallCompleted(            provider = providerConfig.id,            modelId = model,            tokensGenerated = generation.tokensGenerated,            durationMs = generation.durationMs,            costUsd = actualCostUsd,            correlationId = correlationId,        ))        // ─── Step 7: Confidence check ─────────────────────────────────────        val isLowConfidence = isLowConfidence(generation)        val skillOutput = if (isLowConfidence) {            SkillOutput.Partial(                message = generation.text,                warnings = listOf(                    "Cloud response may be incomplete or low-quality. " +                        "Try rephrasing or use a different model.",                ),                data = mapOf(                    "provider" to providerConfig.id,                    "model" to model,                    "tokens_generated" to generation.tokensGenerated.toString(),                    "cost_usd" to actualCostUsd.toString(),                    "finish_reason" to generation.finishReason.name,                    "low_confidence" to "true",                ),            )        } else {            SkillOutput.Success(                message = generation.text,                data = mapOf(                    "provider" to providerConfig.id,                    "model" to model,                    "tokens_generated" to generation.tokensGenerated.toString(),                    "cost_usd" to actualCostUsd.toString(),                    "finish_reason" to generation.finishReason.name,                ),            )        }        return Result.Success(            data = skillOutput,            correlationId = correlationId,            durationNanos = System.nanoTime() - startNanos,            metadata = mapOf(                "provider" to providerConfig.id,                "model" to model,                "tokens" to generation.tokensGenerated.toString(),                "cost" to actualCostUsd.toString(),                "low_confidence" to isLowConfidence.toString(),                "monthly_spent" to costTracker.getTotalSpentThisMonth().toString(),            ),        )    }    /**     * Pick the best cloud provider for this request.     *     * Selection order:     *   1. If [preferredProviderId] is specified and enabled → use it     *   2. Otherwise, pick the first enabled provider (in registry order)     *     * Future: smarter selection based on cost/latency/recent-failures.     */    private fun selectProvider(preferredProviderId: String?): CloudProviderConfig? {        val enabled = registry.getEnabled()        if (enabled.isEmpty()) return null        preferredProviderId?.let { prefId ->            enabled.find { it.id == prefId }?.let { return it }        }        return enabled.first()    }    /**     * Heuristic low-confidence detector (same as LocalLlmLayer).     */    private fun isLowConfidence(result: GenerationResult): Boolean {        if (result.tokensGenerated < lowConfidenceMinTokens) return true        if (result.finishReason == com.roshan.persona.brain.llm.provider.FinishReason.LENGTH) return true        if (result.finishReason == com.roshan.persona.brain.llm.provider.FinishReason.ERROR) return true        if (result.finishReason == com.roshan.persona.brain.llm.provider.FinishReason.OOM) return true        val words = result.text.split(Regex("\\s+")).filter { it.isNotBlank() }        if (words.size >= 10) {            val unique = words.toSet().size            val ratio = unique.toFloat() / words.size            if (ratio < lowConfidenceRepetitionThreshold) return true        }        return false    }    companion object {        const val PROVIDER_CLOUD = "cloud"        /** If generated response has fewer than this many tokens, flag as low-confidence. */        const val DEFAULT_LOW_CONFIDENCE_MIN_TOKENS = 10        /** If word-unique-ratio < this, flag as low-confidence. */        const val DEFAULT_REPETITION_THRESHOLD = 0.4f        /** Estimated tokens added by system prompt + persona template. */        const val ESTIMATED_SYSTEM_PROMPT_TOKENS = 200    }}/** * Helper to expose token estimation on ContextInjector (used by CloudLlmLayer * for budget estimation). */private fun ContextInjector.estimateTokens(text: String): Int =    ContextInjector.HeuristicTokenEstimator.estimate(text)